// 1. Extraer datos base
const raw = $json.output || $json;
const version = raw.version || 1;

// 2. Parsear el JSON (viene como string)
let cotizacion;
try {
  cotizacion = JSON.parse(raw.cotizacion_json);
} catch (e) {
  throw new Error('No se pudo parsear cotizacion_json');
}

// 3. Helpers
const bullets = (arr) =>
  arr && arr.length
    ? arr.map(item => `• ${item}`).join('\n')
    : '• No especificado';

// 4. Construir texto final
const mensaje = `
📄 Cotización
Versión ${version}

OBJETIVO:
${cotizacion.objetivo}

ALCANCE:
${bullets(cotizacion.alcance)}

ENTREGABLES:
${bullets(cotizacion.entregables)}

INVERSIÓN:
Implementación: ${cotizacion.inversion.implementacion.monto}
Mensual: ${cotizacion.inversion.recurrente_mensual.monto}

✍️ Responde directamente con:
• "Aprobado"
• O escribe las correcciones
`.trim();

// 5. Retornar listo para Telegram
return [{
  telegram_message: mensaje
}];

// 1. Obtenemos el objeto principal
const item = $input.first().json;

// 2. Parseamos la cadena 'cotizacion_json'
let cotizacion;
try {
  cotizacion = JSON.parse(item.cotizacion_json);
} catch (e) {
  return { json: { error: "No se pudo leer cotizacion_json", detalle: e.message } };
}

// 3. Función auxiliar para convertir arrays en listas con viñetas
const formatList = (array) => {
  if (!array || !Array.isArray(array)) return "No especificado";
  return array.map(i => `• ${i}`).join('\n');
};

// 4. Preparamos los campos específicos
return {
  json: {
    ...item, // Mantenemos ID, fechas, etc.

    // Texto simple
    objetivo_docs: cotizacion.objetivo || "No especificado",

    // Listas con viñetas
    alcance_docs: formatList(cotizacion.alcance),
    entregables_docs: formatList(cotizacion.entregables),

    // Montos por separado
    monto_implementacion: cotizacion.inversion?.implementacion?.monto || "$0",
    monto_recurrente: cotizacion.inversion?.recurrente_mensual?.monto || "$0",

    // Por si necesitas la moneda por separado
    moneda: cotizacion.inversion?.moneda || "USD"
  }
};

