// Recorremos todos los elementos de entrada
return items.map(item => {
  // Accedemos directamente al objeto cotizacion_json que viene del nodo anterior
  const cot = item.json.cotizacion_json;

  // Validamos que el objeto exista para evitar errores
  if (!cot) {
    return { json: { error: "No se encontró el objeto cotizacion_json" } };
  }

  // 1. Formateamos los arreglos (arrays) para que sean listas con viñetas
  const alcanceTexto = cot.alcance.map(line => `• ${line}`).join('\n');
  const entregablesTexto = cot.entregables.map(line => `• ${line}`).join('\n');

  // 2. Generamos un ID de cotización aleatorio
  const quoteId = Math.floor(Math.random() * 9000) + 1000;

  // 3. Construimos el mensaje final
  // Nota: Ya no usamos .monto porque el string ya incluye el símbolo y la moneda
  const mensaje = `📄 *Cotización #${quoteId}*
*Versión:* ${cot.version}

*OBJETIVO:*
${cot.objetivo}

*ALCANCE:*
${alcanceTexto}

*ENTREGABLES:*
${entregablesTexto}

*INVERSIÓN:*
• *Implementación:* ${cot.inversion.implementacion}
• *Servicio Mensual:* ${cot.inversion.recurrente_mensual}

✍️ *Responde directamente con:*
• "Aprobado"
• O escribe tus correcciones`;

  return {
    json: {
      mensaje_final: mensaje,
      metadata: {
        version: cot.version,
        id_referencia: quoteId,
        estado: cot.estado
      }
    }
  };
});

// Accedemos al mensaje principal
const msg = $('Obtener respuestas del admin').first().json.message;

// La ruta correcta llega hasta 'reply_to_message'
const textoCompleto = msg.reply_to_message?.forum_topic_created?.name;

if (!textoCompleto) {
  return { error: "No se encontró el nombre del tópico en la respuesta" };
}

// Busca el patrón: una Q seguida de números y guiones
const regex = /Q-[\d-]+/; 
const coincidencia = textoCompleto.match(regex);

return {
  // Usamos [0] para obtener la primera coincidencia del array
  quoteId: coincidencia ? coincidencia[0] : null
};
